import {readProgression,validateProgression,DEFAULT_PROGRESSION} from './progression.js';
const fields=[['atSec','Start (s)'],['intervalSec','Attack interval (s)'],['swords','Swords'],['width','Width'],['length','Length'],['sprinkles','Sprinkles']];
export function mountProgressionEditor(host,{config,onSave}){
 let draft=readProgression(config);const $=q=>host.querySelector(q);
 function render(){host.innerHTML='<p class="eyebrow">ENDLESS / YOUR PROGRESSION</p><h2>Build the climb.</h2><p class="muted">Define the stages yourself. Each stage lasts until the next start time; the final stage repeats indefinitely. Saving applies to new endless runs only. Two-minute mode keeps its own standard schedule.</p><div class="progression-globals"></div><div class="progression-table-wrap"><table class="progression-table"><thead><tr><th>Name</th>'+fields.map(([,label])=>'<th>'+label+'</th>').join('')+'<th></th></tr></thead><tbody></tbody></table></div><div class="button-row"><button id="progress-add">Add stage</button><button id="progress-reset">Restore starter stages</button></div><details><summary>Import or export your framework</summary><p class="fine-print">Export produces editable JSON. Paste a saved configuration below to import it.</p><textarea id="progress-json" rows="6" aria-label="Progression JSON"></textarea><div class="button-row"><button id="progress-export">Export JSON</button><button id="progress-import">Import JSON</button></div></details><p id="progress-status" role="status" class="fine-print"></p><button id="progress-save" class="primary">Save endless progression</button>';
  for(const [key,label,scale] of [['firstAttackSec','First attack (seconds)',1],['jitter','Interval variation (%)',100],['breakerStart','Starting breakers (%)',100],['breakerCap','Maximum breakers (%)',100],['breakerRampPairs','Pairs until breaker cap',1]]){const l=document.createElement('label');l.className='field-label';l.textContent=label;const input=document.createElement('input');input.type='number';input.step=key==='jitter'||key.startsWith('breaker')&&key!=='breakerRampPairs'?'0.1':'1';input.value=Number((draft[key]*scale).toFixed(3));input.dataset.progressGlobal=key;input.onchange=()=>draft[key]=input.valueAsNumber/scale;l.append(input);$('.progression-globals').append(l);}
  draft.stages.forEach((s,i)=>{const row=document.createElement('tr');for(const key of ['name',...fields.map(([k])=>k)]){const td=document.createElement('td'),input=document.createElement('input');input.type=key==='name'?'text':'number';input.value=s[key];input.setAttribute('aria-label','Stage '+(i+1)+' '+key);input.dataset.progressStage=i;input.dataset.progressField=key;if(key==='name')input.maxLength=50;else input.step=key==='intervalSec'?'.5':'1';input.onchange=()=>s[key]=key==='name'?input.value:input.valueAsNumber;td.append(input);row.append(td);}const td=document.createElement('td'),remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove stage '+(i+1));remove.disabled=draft.stages.length===1;remove.onclick=()=>{draft.stages.splice(i,1);render();};td.append(remove);row.append(td);$('tbody').append(row);});
  $('#progress-add').onclick=()=>{if(draft.stages.length>=20)return;const last=draft.stages.at(-1);draft.stages.push({...last,name:'Stage '+(draft.stages.length+1),atSec:last.atSec+60});render();};
  $('#progress-reset').onclick=()=>{draft=readProgression(DEFAULT_PROGRESSION);render();};
  $('#progress-import').onclick=()=>{try{draft=validateProgression(JSON.parse($('#progress-json').value));render();$('#progress-status').textContent='Imported draft. Save to use it.';}catch(e){$('#progress-status').textContent=e.message;}};
  $('#progress-export').onclick=()=>{try{const text=JSON.stringify(validateProgression(draft),null,2);$('#progress-json').value=text;const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='swords-pass-endless-progression.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('#progress-status').textContent=e.message;}};
  $('#progress-save').onclick=()=>{try{draft=validateProgression(draft);onSave(draft);$('#progress-status').textContent='Saved. New endless runs will use these stages.';}catch(e){$('#progress-status').textContent=e.message;}};
 }render();
}
